VALUES (1, 1, '{"timestamp": "2025-10-23T10:09:42.229000", "respondent": {"gender": "Female", "age_group": "35-44", "occupation": "Employee", "neighborhood": "Iris"}, "general": {"nbs_familiarity": "No, I have never heard of them", "climate_impact_perception": 5, "climate_adaptation_familiarity": 3, "aware_of_nbs_projects": "No", "information_sources": ["Television and radio", "Print media (newspapers, magazines)", "Social media (Facebook, Instagram, etc.)"], "green_space_frequency": "Once a month or less", "main_site": "Site 1&2: The green space on Alexandru Sahia Street & the green space adjacent to the Someșul Mic River on Nădășel Street"}, "zones": [{"zone_id": "1", "zone_name": "Site 1 – Alexandru Sahia", "problems": ["Pollution (air, noise) caused by traffic", "High temperatures during the summer"], "desired_changes": ["Implementing nature-based solutions to reduce pollution and temperature", "Creating pedestrian routes to encourage walking", "Improving the aesthetic appearance of the area"], "satisfaction": {"satisfaction_neighborhood": 4, "satisfaction_safety": 2, "relaxation_needs_met": 4, "satisfaction_green_spaces_amount": 4, "satisfaction_public_spaces_quality": 3, "satisfaction_noise": 2, "satisfaction_air_quality": 1, "satisfaction_aesthetics": 2, "satisfaction_waste_collection": 1, "satisfaction_green_spaces_access": 4, "satisfaction_disability_access": 1, "satisfaction_public_transport": 1, "satisfaction_pedestrian_infra": 1, "satisfaction_cycling_infra": 3}, "community": {"neighbor_interaction_freq": "Weekly", "outdoor_activities_freq": "Occasionally", "likely_turn_to_neighbor": "Very likely", "sense_of_community": "A weak sense of community"}, "mobility": {"main_transport": "Walking, Bicycle (including e-bikes), Car (passenger)", "walk_frequency": "Weekly", "bike_frequency": "Weekly", "public_transport_frequency": "Monthly", "car_frequency": "Daily", "trip_purpose": ["Work/commute", "Education (school and university)", "Shopping"], "short_trip_preference": ["Bicycle"]}, "qol_factors": ["Information and education on developing nature-based solutions/designs"]}, {"zone_id": "2", "zone_name": "Site 2 – Nădășel", "problems": ["Pollution (air, noise)", "The space is currently used for walking dogs; many people do not clean up after their dogs", "but that is not a major problem. I would ask you to pay special attention", "if you are planning the area for recreational use", "to the residents who live there. It would be very good to think of all the residents and those who live there", "for whom the appearance of a playground behind the house or 5 meters away is not beneficial. I would appreciate it if you planned the area in such a way that both residents and visitors can enjoy a better quality of life. Please do not place recreational areas in the immediate vicinity of houses; the space is large enough for everyone to benefit from peace and comfort. The space offers enough room for walking areas and recreational nature areas. Please bear in mind that a playground in the area has already been modernized", "Armătura Park already exists", "and in two years a mall will also appear", "very close to Nădășel Street. That area is now an excellent habitat for wild animals; every spring we see the pair of pheasants", "wild ducks", "and snakes. Please also take the residents into account", "especially the noise that will be created around their homes. Do not place behind the already existing houses places that can bring large groups of people who will make noise at night or during the day. I would greatly appreciate respecting the area", "nature", "and the residents who have houses there."], "desired_changes": ["Creating green spaces and planting trees", "Creating an alternative mobility corridor", "Experimental area for plantings and nature-based solutions", "In the image provided you can see the house where I live", "namely Nădășel 66", "the white house on the right. The bike lane cannot be drawn farther at the moment", "because the people from Habitat have gardens all the way to the Someș. I would not appreciate seasonal fairs or social spaces being organized behind the house at all; that means noise and disturbance for us. Anyway", "in that area in the evening individuals come who drink and smoke; just look at how the trash bins look in the morning. If you also add seating there", "it will mean continuous calls to the police for those of us in the area. This does not mean you should not arrange the area", "just not so close to the houses. In my opinion", "the construction of spaces should begin at a considerable distance from the last house", "so that those who live there are not disturbed by the noise. If you start any construction", "take the residents as your reference point. I would appreciate there being enough distance in front of the white house for peace and quiet. The area offers enough space to build farther away", "not immediately next to the houses", "because we are talking about an open space where people will inevitably come and make noise. Please think about the development of the area while also taking into account the residents of the area", "who are directly affected by the changes. At the intersection of the streets there is no house", "so you can arrange the wooden area there", "not in front of the house on the left", "which means next to the house where I live. Please survey the area while thinking of us as well. Thank you!"], "satisfaction": {"satisfaction_neighborhood": 4, "satisfaction_safety": 2, "relaxation_needs_met": 4, "satisfaction_green_spaces_amount": 4, "satisfaction_public_spaces_quality": 3, "satisfaction_noise": 2, "satisfaction_air_quality": 1, "satisfaction_aesthetics": 2, "satisfaction_waste_collection": 1, "satisfaction_green_spaces_access": 4, "satisfaction_disability_access": 1, "satisfaction_public_transport": 1, "satisfaction_pedestrian_infra": 1, "satisfaction_cycling_infra": 3}, "community": {"neighbor_interaction_freq": "Weekly", "outdoor_activities_freq": "Occasionally", "likely_turn_to_neighbor": "Very likely", "sense_of_community": "A weak sense of community"}, "mobility": {"main_transport": "Walking, Bicycle (including e-bikes), Car (passenger)", "walk_frequency": "Weekly", "bike_frequency": "Weekly", "public_transport_frequency": "Monthly", "car_frequency": "Daily", "trip_purpose": ["Work/commute", "Education (school and university)", "Shopping"], "short_trip_preference": ["Bicycle"]}, "qol_factors": ["Information and education on developing nature-based solutions/designs"]}, {"zone_id": "3", "zone_name": "Site 3 – Timișului", "problems": ["Unkempt or dirty area"], "desired_changes": ["Promoting walking through appropriate design interventions", "Integrating a green corridor into the public-space structure"], "satisfaction": {"satisfaction_neighborhood": 2, "satisfaction_safety": 1, "relaxation_needs_met": 3, "satisfaction_green_spaces_amount": 3, "satisfaction_public_spaces_quality": 3, "satisfaction_noise": 2, "satisfaction_air_quality": 1, "satisfaction_aesthetics": 1, "satisfaction_waste_collection": 1, "satisfaction_green_spaces_access": 3, "satisfaction_disability_access": 1, "satisfaction_public_transport": 1, "satisfaction_pedestrian_infra": 2, "satisfaction_cycling_infra": 3}, "community": {"neighbor_interaction_freq": "Weekly", "outdoor_activities_freq": "Occasionally", "likely_turn_to_neighbor": "Very likely", "sense_of_community": "A weak sense of community"}, "mobility": {"main_transport": "Walking, Bicycle (including e-bikes), Car (passenger)", "walk_frequency": "A few times/week", "bike_frequency": "A few times/week", "public_transport_frequency": "Monthly", "car_frequency": "Daily", "trip_purpose": ["Work/commute", "Education (school and university)", "Shopping"], "short_trip_preference": ["Bicycle"]}, "qol_factors": ["The existence of green and recreational spaces", "Information and education on developing nature-based solutions/designs"]}, {"zone_id": "4", "zone_name": "Site